!function(r){function t(t){for(var i,e,m=t[0],o=t[1],u=t[2],c=0,g=[];c<m.length;c++)e=m[c],Object.prototype.hasOwnProperty.call(a,e)&&a[e]&&g.push(a[e][0]),a[e]=0;for(i in o)Object.prototype.hasOwnProperty.call(o,i)&&(r[i]=o[i]);for(s&&s(t);g.length;)g.shift()();return n.push.apply(n,u||[]),p()}function p(){for(var r,t=0;t<n.length;t++){for(var p,e=n[t],m=!0,o=1;o<e.length;o++)p=e[o],0!==a[p]&&(m=!1);m&&(n.splice(t--,1),r=i(i.s=e[0]))}return r}function i(t){if(e[t])return e[t].exports;var p=e[t]={i:t,l:!1,exports:{}};return r[t].call(p.exports,p,p.exports,i),p.l=!0,p.exports}var e={},a={13:0},n=[];i.m=r,i.c=e,i.d=function(r,t,p){i.o(r,t)||Object.defineProperty(r,t,{enumerable:!0,get:p})},i.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},i.t=function(r,t){if(1&t&&(r=i(r)),8&t)return r;if(4&t&&"object"==typeof r&&r&&r.__esModule)return r;var p=Object.create(null);if(i.r(p),Object.defineProperty(p,"default",{enumerable:!0,value:r}),2&t&&"string"!=typeof r)for(var e in r)i.d(p,e,function(t){return r[t]}.bind(null,e));return p},i.n=function(r){var t=r&&r.__esModule?function(){return r.default}:function(){return r};return i.d(t,"a",t),t},i.o=function(r,t){return Object.prototype.hasOwnProperty.call(r,t)},i.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=t,m=m.slice();for(var u=0;u<m.length;u++)t(m[u]);var s=o;n.push([76,0]),p()}({76:function(r,t,p){"use strict";p.r(t);var i=p(0);Object(i.a)("ru","army",p(77),p(1))},77:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"军用卡车与军用小车","link":"ru_army#ru_army_mt"}],"model":"嘎斯（GAZ）军用小车","description":"<h6>综述：</h6><p>嘎斯越野吉普和嘎斯轿车是二战期间苏军配备数量众多的自产军用小车，其型号主要有嘎斯（GAZ-61）、嘎斯（GAZ-64）和嘎斯（GAZ-67）等，这些车由苏联嘎斯汽车厂（“高尔基”汽车工厂）生产，是当时二战参战国较有名的军用小车。</p><p>苏军中的嘎斯军用小车，除轿车多数配备给苏军中、高级指挥官使用外，越野吉普车一般都配给前线的苏军中、低级军官用，其中不少是前线指挥部的侦察与通讯用车，也有部分改装为水陆两栖车和消防车。当时，苏联军人认为嘎斯越野吉普（主要指GAZ-64和GAZ-67）能涉水爬坡，能牵引轻型火炮，比美军吉普（根据租借法案，苏军获得了近20000辆美国吉普）越野性能还强；事实上，嘎斯越野吉普可靠性并不高、刹车性能也欠缺，保养难度是很大的，特别是它的油耗大得惊人（油耗0.4升/公里，路况不好时达0.5升/公里），这对当时油料消耗极大的苏军，也是一个极大的缺陷；不过，嘎斯军用小车作为轻便的机动装备，在苏军中是有着重要和积极作用的，亦为苏军取得战争胜利作出了一定贡献。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_mtsGAZ_10.jpg","description":"<h6>嘎斯（GAZ-61）军用小车</h6><p>GAZ-61型是苏联在1938年开始研制的一种军用小车，大多是封闭式轿车，该车虽称越野车，但实际上越野能力并不是很强，在苏军中，这种车基本上为中高级军官所用。</p><p>基本技术数据：</p><p>车长：4.58米，车宽：1.75米，车高：1.9米；</p><p>车重：1.63吨，载重：0.5吨；</p><p>最高车速（公路）：88千米/小时。</p>","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_20.jpg","description":"<h6>嘎斯（GAZ-64）军用小车</h6><p>GAZ-64军用越野小车是GAZ-61的改进型，1941年3月正式生产，其车头灯、车门、挡泥板、座椅、方向盘和车顶帆布等都参照了当时美军吉普车的设计，相对GAZ-61，GAZ-64越野能力有了较大加强，但该型车由于生产时间不长，因此产量不大，从1941年初至1942年末，只生产了680多辆。</p><p>基本技术数据：</p><p>车长：3.3米，车宽：1.53米，车高：1.56米；</p><p>车重：1.3吨，载重：0.4吨；</p><p>最高车速（公路）：92千米/小时；</p><p>发动机：4缸汽油机（3.8升），输出功率：54马力。</p>","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_30.jpg","description":"<h6>嘎斯（GAZ-67）军用吉普车</h6><p>GAZ-67是GAZ-64的改进型，相对GAZ-64，GAZ-67加宽了轮距，并在驾驶员座位下加装了副油箱，使整车性能有所加强。1943年9月，GAZ-67在高尔基汽车厂开始量产，到1944年，又改进为GAZ-67B，从1943年至1945年，GAZ-67（含少量GAZ-67B）一共生产了4800多辆；二战结束后该型车继续生产，至1955年累计生产了9万多辆。</p><p>基本技术数据：</p><p>车长：3.345米，车宽：1.72米，车高：1.7米；</p><p>车重：1.32吨，载重：0.4吨；</p><p>最高车速（公路）：96千米/小时；</p><p>发动机：4缸汽油机（3.3升）；油箱满载油量：70升（每一百公里油耗为15升）。</p>","caption":""}],"part2title":"战场上的嘎斯（GAZ）军用小车","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_mtsGAZ_10.jpg","description":"1941-1942年冬天，东线苏联战场，苏军一辆不明单位的GAZ-61-73军用小车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_11.jpg","description":"1944-1945年，苏军一辆不明单位的GAZ-61-73军用小车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_12.jpg","description":"1939年8月，东线苏联战场，一辆苏军的GAZ-61-40军用小车在伏尔加河沿岸进行上阶梯的测试，该车编号是“Test GK 05-24”。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_13.jpg","description":"1941年秋天，东线苏联战场，停在路边照相的苏军战斗部队一辆GAZ-61-73军用小车，照片中的人物应是司机、军官和警卫。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_14.jpg","description":"1941年8月，东线苏联战场，苏军战斗部队的一辆GAZ-61-417军用小车牵引一部拖车在进行越野测试。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_15.jpg","description":"1942年10月，东线苏联战场，行进在泥泞路上的苏军战斗部队一辆GAZ-61-417军用小车，后面跟着的是2辆BA-64轮式装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_21.jpg","description":"1942年9月，东线苏联战场，隶属苏联斯大林格勒方面军的一辆GAZ-64军用越野小车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_22.jpg","description":"东线苏联战场，苏军一辆GAZ-64军用越野小车正牵引着一门45mm坦克炮向前线进发。该型车的动力不错，在泥泞路上也能轻松地牵引一门轻型火炮行驶。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_23.jpg","description":"1943年夏天，东线苏联战场，苏军的一辆GAZ-64军用越野小车正在小河中涉水行驶，该车后面牵引着一门45mm反坦克炮。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_24.jpg","description":"1941年夏天，东线苏联战场，正准备穿越铁路的苏军一辆GAZ-64军用越野小车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_25.jpg","description":"1942年9月，东线苏联战场，苏军第52装甲旅少校司令和营长在一辆GAZ-64军用越野小车旁研究敌情。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_30.jpg","description":"1944年，东线战场，苏军一辆GAZ-67军用越野吉普车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_31.jpg","description":"1945年5月，德国，苏军（不明单位）的一辆GAZ-67军用越野小车。","caption":""},{"image":"imgs/ru/army/ru_army_mtsGAZ_32.jpg","description":"1944年9月，苏联乌克兰第3方面军以胜利者姿态进入保加利亚首都索菲亚市区，最前面是搭载指挥官的一辆GAZ-67军用越野小车。","caption":""}]}')}});